  function addNonStock(){A.openModal({title:'إضافة صنف غير مخزني',body:`<div class="form-grid"><label class="field full"><span>اسم الصنف / الخدمة</span><input name="name" required></label><label class="field"><span>الكمية</span><input name="qty" type="number" min="0.00000001" step="any" value="1"></label><label class="field"><span>السعر</span><input name="price" type="number" min="0" step="0.01" required></label><label class="field"><span>التصنيف</span><input name="category" value="خدمات / غير مخزني"></label></div>`,onSubmit:fd=>{const d=D(),p={id:A.uid('SRV'),name:fd.get('name').trim(),sku:'',category:fd.get('category').trim()||'خدمات / غير مخزني',imageUrl:'',cost:0,taxRate:selectedTax()?.rate??d.settings.taxRate,lowStock:0,active:true,trackStock:false,temporary:true,units:[{id:A.uid('UNT'),name:'وحدة',factor:1,barcode:'',salePrice:num(fd.get('price')),purchasePrice:0}],createdAt:A.now(),updatedAt:A.now()};d.products.push(p);S.cart.push({id:A.uid('CART'),productId:p.id,unitId:p.units[0].id,qty:Math.max(.00000001,num(fd.get('qty'))),unitPrice:num(fd.get('price')),discount:0});A.saveDB();A.persistCart();renderCashier($('#workspace'))}})}
  function openReturn(){const d=D(),sales=d.sales.filter(x=>x.status!=='returned'&&!A.isSaleLocked?.(x)).slice(0,80);if(!sales.length)return A.toast('لا توجد فواتير قابلة للإرجاع.','warning');A.openModal({title:'مرتجع مبيعات',size:'modal-lg',body:`<div class="form-grid"><label class="field full"><span>الفاتورة</span><select name="saleId">${sales.map(s=>`<option value="${s.id}">${esc(s.number)} — ${esc(s.customerName)} — ${A.money(s.total)}</option>`).join('')}</select></label><label class="field"><span>طريقة معالجة المدفوع</span><select name="refundMode"><option value="cash">إرجاع المبلغ من حساب الدفع</option><option value="credit">إضافة المبلغ رصيداً لصالح العميل</option></select></label><label class="field full"><span>السبب</span><input name="reason" required></label></div>`,submitText:'ترحيل المرتجع',submitIcon:'refresh',onSubmit:fd=>{if(!A.has('sales_return')&&!A.has('sales'))throw Error('لا تملك صلاحية المرتجعات.');const sale=d.sales.find(x=>x.id===fd.get('saleId'));if(!sale||sale.status==='returned')throw Error('الفاتورة غير صالحة للإرجاع.');const customer=d.customers.find(x=>x.id===sale.customerId),refundMode=fd.get('refundMode'),paid=num(sale.paid);A.reverseSaleEffect(sale,{markReturned:true});if(refundMode==='credit'&&paid>0&&customer&&!customer.system){const pays=(sale.payments?.length?sale.payments:[{accountId:d.settings.defaultAccountId||'ACC-1110',amount:paid}]);for(const p of pays)A.postJournal(`تحويل مرتجع إلى رصيد عميل ${sale.number}`,sale.number,[{accountId:p.accountId,debit:num(p.amount),credit:0},{accountId:'ACC-1200',debit:0,credit:num(p.amount)}],A.today(),true);customer.balance=Number((num(customer.balance)-paid).toFixed(2))}sale.returnReason=fd.get('reason');sale.refundMode=refundMode;A.audit('مرتجع مبيعات','الكاشير',`${sale.number} — ${fd.get('reason')}`);A.saveDB();A.toast('تم ترحيل المرتجع وإعادة المخزون وعكس الحسابات');A.renderCurrent()}})}

  A.cashierTotals=totals;A.cashierSelectedCustomer=selectedCustomer;A.cashierActiveWarehouse=activeWarehouse;A.cashierSelectedTax=selectedTax;A.cashierResetAfterSale=()=>{S.cart=[];resetCashierPayment();A.persistCart()};A.cashierRender=()=>renderCashier($('#workspace'));
