  let scanBuffer='',scanLast=0;document.addEventListener('keydown',e=>{if(S.view!=='cashier'||S.financialPreviewMode)return;if(e.key==='F2'){e.preventDefault();(window.innerWidth>900?$('#cashierSearchDesktop'):$('#cashierSearch'))?.focus({preventScroll:true});return}if(e.key==='F8'){e.preventDefault();checkout(false);return}if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;const time=Date.now();if(time-scanLast>80)scanBuffer='';scanLast=time;if(e.key==='Enter'){if(scanBuffer.length>=3){scanCode(scanBuffer);scanBuffer=''}return}if(e.key.length===1)scanBuffer+=e.key});

  function refreshCashierStockBadges(){
    if(S.view!=='cashier')return;const wh=activeWarehouse();if(!wh)return;
    document.querySelectorAll('.product-card[data-id]').forEach(card=>{const p=D().products.find(x=>x.id===card.dataset.id);if(!p)return;const variants=p.hasVariants?variantChildrenFor(p):[],stock=p.hasVariants?variants.reduce((a,v)=>a+productStock(v),0):productStock(p),stockText=p.hasVariants?(variants.length?`${variants.length} متغير<br>${A.unitBreakdownHtml(p,stock,{includeZero:true})}`:'متغيرات غير مولدة'):p.useRecipe?'وصفة / حسب المكونات':p.trackStock===false?'غير مخزني':A.unitBreakdownHtml(p,stock,{includeZero:true}),badge=card.querySelector('.product-stock');if(badge)badge.innerHTML=stockText;card.classList.toggle('out-of-stock',p.trackStock!==false&&!p.useRecipe&&!p.hasVariants&&stock<=0)})
  }
