  function liveRerenderCashier(detail={},manual=false){
    if(S.view!=='cashier')return;const datasets=new Set(detail?.datasets||detail?.changedDatasets||[]),root=document.getElementById('workspace');if(!root)return;
    const structural=manual||['products','categories','warehouses','branches','itemPrices','priceGroups','customerGroups','customers','taxes'].some(x=>datasets.has(x));
    if(structural){
      const active=document.activeElement,activeId=active?.id||'',activeValue=active&&'value'in active?active.value:null,selection=active&&typeof active.selectionStart==='number'?[active.selectionStart,active.selectionEnd]:null,winX=window.scrollX,winY=window.scrollY,productPane=root.querySelector('.products-pane'),cartPane=root.querySelector('.cart-items'),categoryPane=root.querySelector('.cashier-filters'),productScroll=productPane?.scrollTop||0,cartScroll=cartPane?.scrollTop||0,categoryScroll=categoryPane?.scrollLeft??S.cashierCategoryScroll??0;
      // لا نهدم نافذة دفع مفتوحة؛ البيانات وصلت وسنحدّثها بعد إغلاق النافذة.
      if(document.getElementById('modalRoot')?.children?.length){S.pendingCashierSyncRefresh=true;refreshCashierStockBadges();refreshCashierCustomersLive();return}
      S.cashierCategoryScroll=categoryScroll;renderCashier(root);requestAnimationFrame(()=>{root.querySelector('.products-pane')?.scrollTo(0,productScroll);root.querySelector('.cart-items')?.scrollTo(0,cartScroll);const nextCategoryPane=root.querySelector('.cashier-filters');if(nextCategoryPane)try{nextCategoryPane.scrollLeft=categoryScroll}catch(_){}window.scrollTo(winX,winY);if(activeId){const next=document.getElementById(activeId);if(next){if(activeValue!=null&&'value'in next)next.value=activeValue;next.focus({preventScroll:true});if(selection&&typeof next.setSelectionRange==='function')try{next.setSelectionRange(selection[0],selection[1])}catch(_){}}}})
    }else{if(!datasets.size||datasets.has('stock')||datasets.has('sales')||datasets.has('purchases')||datasets.has('transfers'))refreshCashierStockBadges();if(datasets.has('customers'))refreshCashierCustomersLive()}
    if(S.cashierEditingSaleId||S.cashierInvoiceManual)return;const input=document.getElementById('cashierInvoiceNo');if(input&&document.activeElement!==input)input.value=previewInvoiceNo()
  }
